css:
#dayprint .ps7, #dayprint .ps7 *{box-sizing:border-box;}
#dayprint .ps7{font:7.2pt/1.16 "Calibri","Segoe UI",system-ui,sans-serif; color:#15181a; margin:0;}
#dayprint .ps7.ps{page-break-inside:avoid;}
#dayprint .ps7.ps{page-break-inside:avoid;}
#dayprint .ps7 .brk{page-break-before:always;}
#dayprint .ps7 .psh{display:flex; align-items:center; gap:10px; background:#15181a; color:#fff; padding:3px 8px;}
#dayprint .ps7 .psh-l b{font-size:13.5pt; letter-spacing:.2px; display:block; line-height:1;}
#dayprint .ps7 .psh-l span{font-size:6pt; letter-spacing:1.6px; color:#c9cfd2;}
#dayprint .ps7 .psh-m{flex:1; text-align:center;}
#dayprint .ps7 .psh-m .kicker{font-size:6.4pt; letter-spacing:2.1px; color:#f07c2a; display:block;}
#dayprint .ps7 .psh-m h1{font-size:11pt; margin:0; font-weight:700;}
#dayprint .ps7 .psh-r{text-align:right; font-size:6.6pt; letter-spacing:.9px; color:#c9cfd2;}
#dayprint .ps7 .psh-r b{display:block; font-size:9pt; color:#fff; letter-spacing:.6px;}
#dayprint .ps7 .psh-r span{display:block;}
#dayprint .ps7 .lede{margin:1px 0 2px; font-size:7pt; color:#3b4246; display:flex; align-items:center; gap:8px;}
#dayprint .ps7 .lede b{color:#15181a;}
#dayprint .ps7 .tag{margin-left:auto; border:1px solid #f07c2a; color:#b4521a; font-size:6.6pt; letter-spacing:1.1px;
 padding:2px 7px; white-space:nowrap;}
#dayprint .ps7 h2{font-size:6.8pt; letter-spacing:.5px; margin:2px 0 1.5px; border-bottom:1px solid #15181a; padding-bottom:2px;
 display:flex; align-items:baseline; gap:6px; font-weight:700;}
#dayprint .ps7 h2 i{font-style:normal; color:#f07c2a; font-size:7.4pt;}
#dayprint .ps7 h2 em{margin-left:auto; font-style:italic; font-weight:400; font-size:7pt; color:#6b757a;}
#dayprint .ps7 .swmsh{border:1px solid #f07c2a; border-left:2.5px solid #f07c2a; padding:1.5px 5px; margin:1px 0 2px;
 background:#fff8f3;}
#dayprint .ps7 .swmsh p{margin:0; font-size:5.8pt; line-height:1.2; color:#3b4246;}
#dayprint .ps7 .swmsh b{color:#15181a;}
#dayprint .ps7 .swmsh p i{color:#8b9498; font-style:italic;}
#dayprint .ps7 .swmsh .bx{width:6.2px; height:6.2px; margin:0 2px 0 5px;}
#dayprint .ps7 .swmsh .bx.checked::after{font-size:5pt; left:.4px; top:-1.8px;}
#dayprint .ps7 .today{display:grid; grid-template-columns:repeat(5,1fr); gap:4px;}
#dayprint .ps7 .today div{border:1px solid #b9c1c5; padding:2px 4px; min-height:24px;}
#dayprint .ps7 .today label{display:block; font-size:6.2pt; letter-spacing:.8px; color:#6b757a;}
#dayprint .ps7 .today b{display:block; font-size:7.6pt; margin-top:1px;}
#dayprint .ps7 .today span{display:block; font-size:6pt; color:#8b9498; font-style:italic; margin-top:1px;}
#dayprint .ps7 .work{display:grid; grid-template-columns:repeat(4,1fr); gap:0 9px;}
#dayprint .ps7 .wk, #dayprint .ps7 .rl{display:flex; align-items:flex-start; gap:3px; font-size:6.5pt; padding:.2px 0;}
#dayprint .ps7 .bx{width:8.5px; height:8.5px; border:1px solid #6b757a; display:inline-block; flex:none; margin-top:1.5px;}
#dayprint .ps7 .bx.checked{background:#15181a; border-color:#15181a; position:relative;}
#dayprint .ps7 .bx.checked::after{content:"✓"; color:#fff; font-size:7pt; position:absolute; left:.6px; top:-1.4px;}
#dayprint .ps7 .hzs{display:grid; grid-template-columns:1fr 1fr 1fr; gap:0 7px;}
#dayprint .ps7 .hzs.hz4{grid-template-columns:1fr 1fr 1fr 1fr; gap:0 6px;}
#dayprint .ps7 .hz4 .hz p{font-size:5.5pt; line-height:1.14;}
#dayprint .ps7 .hz{border-left:2px solid #f07c2a; padding:1px 0 1px 5px;}
#dayprint .ps7 .hz label{display:flex; gap:3px; align-items:flex-start; font-size:6.5pt;}
#dayprint .ps7 .hz p{margin:0 0 0 10px; font-size:5.7pt; line-height:1.17; color:#3b4246;}
#dayprint .ps7 .hz span{display:block; margin-left:10px; font-size:5pt; color:#8b9498;}
#dayprint .ps7 .rules{display:grid; grid-template-columns:1fr 1fr 1fr; gap:0 9px;}
#dayprint .ps7 .rules.rl4{grid-template-columns:1fr 1fr 1fr 1fr; gap:0 7px;}
#dayprint .ps7 .rl4 .rl{font-size:6.2pt;}
#dayprint .ps7 .emg{display:grid; grid-template-columns:1.35fr 1fr 1fr; gap:5px;}
#dayprint .ps7 .emg>div{border:1px solid #b9c1c5; padding:3px 6px;}
#dayprint .ps7 .emg-000{border:1.4px solid #c0392b !important;}
#dayprint .ps7 .emg-h{font-size:6.2pt; letter-spacing:1.1px; color:#6b757a; margin-bottom:2px;}
#dayprint .ps7 .emg-n{font-size:12pt; font-weight:700; color:#c0392b; line-height:1;}
#dayprint .ps7 .emg-s{font-size:6pt; color:#3b4246; margin-top:1px;}
#dayprint .ps7 .emg-r{display:flex; justify-content:space-between; gap:6px; font-size:6.2pt; padding:.3px 0;}
#dayprint .ps7 .emg-r b{white-space:nowrap;}
#dayprint .ps7 .rule{display:inline-block; width:78px; border-bottom:1px solid #6b757a;}
#dayprint .ps7 .so{width:100%; border-collapse:collapse; table-layout:fixed;}
#dayprint .ps7 .so th{font-size:5.9pt; letter-spacing:.7px; color:#6b757a; text-align:left; border-bottom:1px solid #15181a;
 padding:2px 3px; font-weight:600;}
#dayprint .ps7 .so td{border-bottom:1px solid #d5dadd; height:9px; padding:0 3px;}
#dayprint .ps7 .so tbody tr:nth-child(even){background:#f4f6f7;}
#dayprint .ps7 .so col{}
#dayprint .ps7 .so .n{width:14px; color:#8b9498; font-size:6.4pt;}
#dayprint .ps7 .so .fit{white-space:nowrap;}
#dayprint .ps7 .so .fit i{vertical-align:-1px;}
#dayprint .ps7 .so .fit span{font-size:6.2pt; color:#6b757a; margin:0 5px 0 2px;}
#dayprint .ps7 .confirm{font-size:5.2pt; line-height:1.18; color:#3b4246; margin:1.5px 0 1px;}
#dayprint .ps7 .raise{display:grid; grid-template-columns:2.6fr 1fr 1fr .6fr; gap:5px;}
#dayprint .ps7 .raise div{border:1px solid #b9c1c5; min-height:24px; padding:2px 4px;}
#dayprint .ps7 .raise label{font-size:5.8pt; letter-spacing:.6px; color:#6b757a;}
#dayprint .ps7 .foot{font-size:5pt; color:#8b9498; margin:1.5px 0 0; border-top:1px solid #d5dadd; padding-top:1.5px;}
#dayprint .ps7 .story{margin:1px 0 2px; padding:0 0 0 10px; font-size:6.1pt; line-height:1.2;}
#dayprint .ps7 .story li{margin:0 0 1px;}
#dayprint .ps7 .story b{color:#15181a;}
#dayprint .ps7 .lds{width:100%; border-collapse:collapse; font-size:5.7pt; margin:1px 0 1.5px;}
#dayprint .ps7 .lds th{background:#eef1f2; text-align:left; padding:1px 4px; border:1px solid #cfd5d8; font-size:5.8pt;
 letter-spacing:.3px; text-transform:uppercase; color:#5d686d;}
#dayprint .ps7 .lds td{padding:.5px 3px; border:1px solid #d5dadd; vertical-align:top;}
#dayprint .ps7 .lds td.n{text-align:center; color:#8b9498;}
#dayprint .ps7 .none{font-size:7pt; color:#5d686d; margin:2px 0 4px;}
#dayprint .ps7 .rl2{color:#8b9498; font-size:5.6pt;}
#dayprint .ps7 .sotwo{display:grid; grid-template-columns:1fr 1fr; gap:0 10px;}
#dayprint .ps7 .lsr{display:grid; grid-template-columns:1fr 1fr; gap:1px 6px; margin:1px 0 2px;}
#dayprint .ps7 .lsrow{display:flex; align-items:stretch; border:1px solid #d5dadd; border-radius:3px; overflow:hidden;}
#dayprint .ps7 .lsrn{flex:0 0 26%; display:flex; align-items:center; padding:2px 5px; color:#fff; font-weight:700;
 font-size:6pt; line-height:1.1; letter-spacing:.1px;}
#dayprint .ps7 .lsrt{flex:1 1 auto; padding:2px 5px; font-size:5.8pt; line-height:1.2; background:#f4f6f7;}
#dayprint .ps7 .lsrt .bx{float:left; margin:.5pt 4px 0 0;}
#dayprint .ps7 .lsr-a{background:#c8463c;}
#dayprint .ps7 .lsr-b{background:#8a8352;}
#dayprint .ps7 .lsr-c{background:#3c4247;}
#dayprint .ps7 .lsr-d{background:#ef6b1e;}
#dayprint .ps7 .lsr-e{background:#4d7141;}
#dayprint .ps7 .lsr-f{background:#1f3a5f;}
#dayprint .ps7 .so{page-break-inside:avoid;}
#dayprint .ps7 .hold{page-break-inside:avoid;}
#dayprint .ps7.ps.fen{font-size:6.85pt;}
#dayprint .ps7.fen .hzs.hz4 .hz p{font-size:5.25pt; line-height:1.12;}
#dayprint .ps7.fen .hzs.hz4 .hz label{font-size:6.2pt;}
#dayprint .ps7.fen .hzs.hz4 .hz span{font-size:4.8pt;}
#dayprint .ps7.fen .so td, #dayprint .ps7.fen .so th{padding-top:.4px; padding-bottom:.4px; font-size:6.1pt;}
#dayprint .ps7.fen .so .rl2{font-size:5.5pt;}
#dayprint .ps7.fen .today div{min-height:21px;}
#dayprint .ps7.fen .emg>div{padding-top:2px; padding-bottom:2px;}
#dayprint .ps7.fen .emg{font-size:6.4pt;}
#dayprint .ps7.fen .lsr{font-size:6.2pt;}
#dayprint .ps7.fen h2{margin:1.5px 0 1px;}
#dayprint .ps7.fen .confirm, #dayprint .ps7.fen .foot{font-size:5.4pt; line-height:1.15;}
#dayprint .ps7 .today.mfill{grid-template-columns:repeat(3,1fr);}
#dayprint .ps7 .today.mfill div{min-height:26px;}
#dayprint .ps7 .wl{display:block; border-bottom:1px solid #98a3a8; height:11px; margin-top:3px;}
#dayprint .ps7 .mlines{display:grid; gap:7px; margin:2px 0 3px;}
#dayprint .ps7 .mlines .wl{height:13px;}
#dayprint .ps7.fen .lds{font-size:5.5pt;}
#dayprint .ps7.fen .lds td{padding-top:.2px; padding-bottom:.2px;}
#dayprint .ps7.fen .lds th{padding-top:.4px; padding-bottom:.4px;}
#dayprint .ps7.fen .story{font-size:5.9pt; line-height:1.17;}
#dayprint .ps7.fen .wk{font-size:6.2pt;}
#dayprint .ps7 .hzs.hz4{display:block;column-count:4;column-gap:6px} #dayprint .ps7 .hzs.hz4 .hz{break-inside:avoid;margin-bottom:1.5px}
#dayprint .ps7 .sotwo{grid-template-columns:minmax(0,1fr) minmax(0,1fr)} #dayprint .ps7 .sotwo>table{min-width:0;width:100%}
